module ct_vfmau_lza_simd_half(
  addend,                           // input  [23:0]
  lza_result,                       // output [4:0]
  lza_result_zero,                  // output
  sub_vld,                          // input
  summand                           // input  [23:0]
);

input   [23:0]  addend;
input           sub_vld;
input   [23:0]  summand;
output  [4 :0]  lza_result;
output          lza_result_zero;

// Carry signals
wire    [23:0]  carry_p;
wire    [23:0]  carry_g;
wire    [23:0]  carry_d;
wire    [23:0]  lza_precod;

assign carry_p[23:0] = summand[23:0] ^ addend[23:0];   // propagate
assign carry_g[23:0] = summand[23:0] & addend[23:0];   // generate
assign carry_d[23:0] = ~(summand[23:0] | addend[23:0]); // delete

// Pre-code bit 0 (special case — uses carry_p[1])
assign lza_precod[0] =
     carry_p[1] && (carry_g[0] && sub_vld || carry_d[0])
 || !carry_p[1] && (carry_d[0] && sub_vld || carry_g[0]);

// Pre-code bit 23 (special case — MSB boundary)
assign lza_precod[23] =
     sub_vld && (carry_g[23] && !carry_d[22] || carry_d[23] && !carry_g[22])
 || !sub_vld && (carry_d[23] && !carry_d[22] || !carry_d[23]);

// Pre-code bits [22:1] (general case — uses carry_p[i+1], carry_g/d[i], carry_g/d[i-1])
assign lza_precod[22:1] =
    carry_p[23:2] & (carry_g[22:1] & ~carry_d[21:0] | carry_d[22:1] & ~carry_g[21:0])
 | ~carry_p[23:2] & (carry_g[22:1] & ~carry_g[21:0] | carry_d[22:1] & ~carry_d[21:0]);

// Priority encoding implementation
// Find the position of the first '1' in lza_precod (MSB-first)

// Split lza_precod into segments
wire [3:0] lza_precod_upper;    // bits 23-20
wire [3:0] lza_precod_middle;   // bits 19-16
wire [3:0] lza_precod_lower;    // bits 15-12
wire [3:0] lza_precod_rest;     // bits 11-8
wire [3:0] lza_precod_last;     // bits 7-4
wire [3:0] lza_precod_tail;     // bits 3-0

assign lza_precod_upper = lza_precod[23:20];
assign lza_precod_middle = lza_precod[19:16];
assign lza_precod_lower = lza_precod[15:12];
assign lza_precod_rest = lza_precod[11:8];
assign lza_precod_last = lza_precod[7:4];
assign lza_precod_tail = lza_precod[3:0];

// Step 1: Use 4:2 LZA compressors for each segment
wire lza_p0_upper;
wire lza_p1_upper;
wire lza_vld_upper;
wire lza_p0_middle;
wire lza_p1_middle;
wire lza_vld_middle;
wire lza_p0_lower;
wire lza_p1_lower;
wire lza_vld_lower;
wire lza_p0_rest;
wire lza_p1_rest;
wire lza_vld_rest;
wire lza_p0_last;
wire lza_p1_last;
wire lza_vld_last;
wire lza_p0_tail;
wire lza_p1_tail;
wire lza_vld_tail;

ct_vfmau_lza_42 lza_42_upper (
    .lza_p0(lza_p0_upper),
    .lza_p1(lza_p1_upper),
    .lza_precod(lza_precod_upper),
    .lza_vld(lza_vld_upper)
);

ct_vfmau_lza_42 lza_42_middle (
    .lza_p0(lza_p0_middle),
    .lza_p1(lza_p1_middle),
    .lza_precod(lza_precod_middle),
    .lza_vld(lza_vld_middle)
);

ct_vfmau_lza_42 lza_42_lower (
    .lza_p0(lza_p0_lower),
    .lza_p1(lza_p1_lower),
    .lza_precod(lza_precod_lower),
    .lza_vld(lza_vld_lower)
);

ct_vfmau_lza_42 lza_42_rest (
    .lza_p0(lza_p0_rest),
    .lza_p1(lza_p1_rest),
    .lza_precod(lza_precod_rest),
    .lza_vld(lza_vld_rest)
);

ct_vfmau_lza_42 lza_42_last (
    .lza_p0(lza_p0_last),
    .lza_p1(lza_p1_last),
    .lza_precod(lza_precod_last),
    .lza_vld(lza_vld_last)
);

ct_vfmau_lza_42 lza_42_tail (
    .lza_p0(lza_p0_tail),
    .lza_p1(lza_p1_tail),
    .lza_precod(lza_precod_tail),
    .lza_vld(lza_vld_tail)
);

// Step 2: Convert position code from compressors to count from MSB
// The position code from 4:2 compressor is:
// bit23 → 00 → 0 → count 0
// bit22 → 01 → 1 → count 1
// bit21 → 10 → 2 → count 2
// bit20 → 11 → 3 → count 3
// Similarly for lower bits

// Convert the position from the compressor to the desired result
wire [4:0] lza_result_upper;
wire [4:0] lza_result_middle;
wire [4:0] lza_result_lower;
wire [4:0] lza_result_rest;
wire [4:0] lza_result_last;
wire [4:0] lza_result_tail;

assign lza_result_upper = 
    (lza_vld_upper) ? 
        ((lza_p1_upper << 1) | lza_p0_upper) : 5'd24;

assign lza_result_middle = 
    (lza_vld_middle) ? 
        ((lza_p1_middle << 1) | lza_p0_middle) + 4 : 5'd24;

assign lza_result_lower = 
    (lza_vld_lower) ? 
        ((lza_p1_lower << 1) | lza_p0_lower) + 8 : 5'd24;

assign lza_result_rest = 
    (lza_vld_rest) ? 
        ((lza_p1_rest << 1) | lza_p0_rest) + 12 : 5'd24;

assign lza_result_last = 
    (lza_vld_last) ? 
        ((lza_p1_last << 1) | lza_p0_last) + 16 : 5'd24;

assign lza_result_tail = 
    (lza_vld_tail) ? 
        ((lza_p1_tail << 1) | lza_p0_tail) + 20 : 5'd24;

// Step 3: Combine the results starting from the upper chunk
wire [4:0] lza_result_encoded;

assign lza_result_encoded = 
    (lza_vld_upper) ? lza_result_upper :
    (lza_vld_middle) ? lza_result_middle :
    (lza_vld_lower) ? lza_result_lower :
    (lza_vld_rest) ? lza_result_rest :
    (lza_vld_last) ? lza_result_last :
    (lza_vld_tail) ? lza_result_tail : 5'd24;

assign lza_result = lza_result_encoded;

// Check if all bits are zero
assign lza_result_zero = 
    (~lza_vld_upper) && 
    (~lza_vld_middle) && 
    (~lza_vld_lower) && 
    (~lza_vld_rest) && 
    (~lza_vld_last) && 
    (~lza_vld_tail);

endmodule

module ct_vfmau_lza_simd_half(
  addend,                           // input  [23:0]
  lza_result,                       // output [4 :0]
  lza_result_zero,                  // output
  sub_vld,                          // input
  summand                           // input  [23:0]
);

input   [23:0]  addend;
input           sub_vld;
input   [23:0]  summand;
output  [4 :0]  lza_result;
output          lza_result_zero;

// Carry signals
wire    [23:0]  carry_p;
wire    [23:0]  carry_g;
wire    [23:0]  carry_d;
wire    [23:0]  lza_precod;

assign carry_p[23:0] = summand[23:0] ^ addend[23:0];   // propagate
assign carry_g[23:0] = summand[23:0] & addend[23:0];   // generate
assign carry_d[23:0] = ~(summand[23:0] | addend[23:0]); // delete

// Pre-code bit 0 (special case — uses carry_p[1])
assign lza_precod[0] =
     carry_p[1] && (carry_g[0] && sub_vld || carry_d[0])
 || !carry_p[1] && (carry_d[0] && sub_vld || carry_g[0]);

// Pre-code bit 23 (special case — MSB boundary)
assign lza_precod[23] =
     sub_vld && (carry_g[23] && !carry_d[22] || carry_d[23] && !carry_g[22])
 || !sub_vld && (carry_d[23] && !carry_d[22] || !carry_d[23]);

// Pre-code bits [22:1] (general case — uses carry_p[i+1], carry_g/d[i], carry_g/d[i-1])
assign lza_precod[22:1] =
    carry_p[23:2] & (carry_g[22:1] & ~carry_d[21:0] | carry_d[22:1] & ~carry_g[21:0])
 | ~carry_p[23:2] & (carry_g[22:1] & ~carry_g[21:0] | carry_d[22:1] & ~carry_d[21:0]);

// Group bits into 6 groups of 4 bits each
wire [3:0] lza_group0 = {lza_precod[23], lza_precod[22], lza_precod[21], lza_precod[20]};
wire [3:0] lza_group1 = {lza_precod[19], lza_precod[18], lza_precod[17], lza_precod[16]};
wire [3:0] lza_group2 = {lza_precod[15], lza_precod[14], lza_precod[13], lza_precod[12]};
wire [3:0] lza_group3 = {lza_precod[11], lza_precod[10], lza_precod[9], lza_precod[8]};
wire [3:0] lza_group4 = {lza_precod[7], lza_precod[6], lza_precod[5], lza_precod[4]};
wire [3:0] lza_group5 = {lza_precod[3], lza_precod[2], lza_precod[1], lza_precod[0]};

// Use 4:2 compressors for each group
wire lza0_p0, lza0_p1, lza0_vld;
wire lza1_p0, lza1_p1, lza1_vld;
wire lza2_p0, lza2_p1, lza2_vld;
wire lza3_p0, lza3_p1, lza3_vld;
wire lza4_p0, lza4_p1, lza4_vld;
wire lza5_p0, lza5_p1, lza5_vld;

ct_vfmau_lza_42 lza0_inst (
  .lza_precod(lza_group0),
  .lza_p0(lza0_p0),
  .lza_p1(lza0_p1),
  .lza_vld(lza0_vld)
);

ct_vfmau_lza_42 lza1_inst (
  .lza_precod(lza_group1),
  .lza_p0(lza1_p0),
  .lza_p1(lza1_p1),
  .lza_vld(lza1_vld)
);

ct_vfmau_lza_42 lza2_inst (
  .lza_precod(lza_group2),
  .lza_p0(lza2_p0),
  .lza_p1(lza2_p1),
  .lza_vld(lza2_vld)
);

ct_vfmau_lza_42 lza3_inst (
  .lza_precod(lza_group3),
  .lza_p0(lza3_p0),
  .lza_p1(lza3_p1),
  .lza_vld(lza3_vld)
);

ct_vfmau_lza_42 lza4_inst (
  .lza_precod(lza_group4),
  .lza_p0(lza4_p0),
  .lza_p1(lza4_p1),
  .lza_vld(lza4_vld)
);

ct_vfmau_lza_42 lza5_inst (
  .lza_precod(lza_group5),
  .lza_p0(lza5_p0),
  .lza_p1(lza5_p1),
  .lza_vld(lza5_vld)
);

// Convert 2-bit position code to 5-bit result for each group
wire [4:0] group_result0, group_result1, group_result2, group_result3, group_result4, group_result5;

assign group_result0 = (lza0_vld) ? ({lza0_p1, lza0_p0} + 0) : 5'd24;
assign group_result1 = (lza1_vld) ? ({lza1_p1, lza1_p0} + 4) : 5'd24;
assign group_result2 = (lza2_vld) ? ({lza2_p1, lza2_p0} + 8) : 5'd24;
assign group_result3 = (lza3_vld) ? ({lza3_p1, lza3_p0} + 12) : 5'd24;
assign group_result4 = (lza4_vld) ? ({lza4_p1, lza4_p0} + 16) : 5'd24;
assign group_result5 = (lza5_vld) ? ({lza5_p1, lza5_p0} + 20) : 5'd24;

// Determine the highest set bit
wire [4:0] result;
assign result = 
    (lza0_vld && group_result0 < 24) ? group_result0 : 
    (lza1_vld && group_result1 < 24) ? group_result1 : 
    (lza2_vld && group_result2 < 24) ? group_result2 : 
    (lza3_vld && group_result3 < 24) ? group_result3 : 
    (lza4_vld && group_result4 < 24) ? group_result4 : 
    (lza5_vld && group_result5 < 24) ? group_result5 : 
    5'd24;

// Check if all bits are zero
assign lza_result = result;
assign lza_result_zero = (lza0_vld == 0) && 
                         (lza1_vld == 0) && 
                         (lza2_vld == 0) && 
                         (lza3_vld == 0) && 
                         (lza4_vld == 0) && 
                         (lza5_vld == 0);

endmodule
